CREATE TABLE permissions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

    api_label text NOT NULL UNIQUE,

    display_name text NOT NULL,

    description text,

    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,

    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    deleted_at timestamptz,

    is_active boolean NOT NULL DEFAULT true,
    is_deleted boolean NOT NULL DEFAULT false
);

CREATE INDEX idx_permissions_active_catalog
ON permissions(api_label)
WHERE is_active = true AND is_deleted = false;

CREATE INDEX idx_permissions_metadata_gin
ON permissions USING gin(metadata);

ON CONFLICT (api_label) DO NOTHING;
